<?php
/**
 * DevWP WordPress worker — generated by DevWP from
 * config/frankenphp/template-worker.php. Do not edit.
 *
 * Boots WordPress once per worker thread, then serves requests through
 * frankenphp_handle_request(), resetting per-request global state first.
 * See the "Worker mode" notes in docs/architecture.md for the design.
 */

$site_root = '{{ABS_SITE_ROOT}}';

if ( ! is_file( $site_root . '/wp-load.php' ) ) {
	// WordPress is not installed (yet). Exit-crash-looping here would take
	// the whole FrankenPHP process down after a few restarts, so serve 503s
	// until the worker is restarted with WordPress present.
	$not_installed = static function () use ( $site_root ): void {
		http_response_code( 503 );
		header( 'Content-Type: text/plain' );
		echo "DevWP: WordPress is not installed in {$site_root} yet.\n";
	};
	while ( frankenphp_handle_request( $not_installed ) ) {
		// Keep serving until the worker is restarted.
	}
	return;
}

// Plain require, deliberately not wp-blog-header.php: that file uses
// require_once for wp-load.php and template-loader.php plus a $wp_did_header
// guard, so every request after the first per worker would render empty.
// wp-load.php bootstraps WordPress (plugins_loaded … wp_loaded) exactly once.
require $site_root . '/wp-load.php';

// Snapshot the hook registry after boot. Plugins may add callbacks at
// runtime (including direct $wp_filter manipulation), which must not leak
// across requests. WP_Hook is mutable, so each entry needs a clone — a
// shallow array copy would share the objects.
$boot_filter = array_map( fn( $hook ) => clone $hook, $GLOBALS['wp_filter'] );

$handler = static function () use ( $boot_filter ): void {
	// Per-request reset BEFORE wp(). wp_magic_quotes() is called by
	// wp-settings.php at boot only — never inside wp() — and superglobals
	// arrive unslashed after frankenphp_handle_request(), so this applies
	// magic quotes exactly once per request.
	if ( function_exists( 'wp_magic_quotes' ) ) {
		wp_magic_quotes();
	}

	// Identity and render state must not leak between requests.
	// $_wp_theme_features is deliberately NOT reset: it is boot state
	// registered during after_setup_theme, which does not fire per request.
	unset(
		$GLOBALS['current_user'],
		$GLOBALS['wp_styles'],
		$GLOBALS['wp_scripts'],
		$GLOBALS['wp_filesystem']
	);

	// Reset the query/result state of the persistent wpdb instance (the
	// object itself is boot state and is intentionally reused).
	if ( isset( $GLOBALS['wpdb'] ) && method_exists( $GLOBALS['wpdb'], 'flush' ) ) {
		$GLOBALS['wpdb']->flush();
	}

	// Restore the boot-time hook registry (fresh clones again — the copies
	// installed by the previous request may have been mutated).
	$GLOBALS['wp_filter'] = array_map( fn( $hook ) => clone $hook, $boot_filter );

	// Fresh object cache per request — classic-mode cache parity (with a
	// Redis drop-in, Redis stays the shared L2 across workers/requests).
	if ( function_exists( 'wp_cache_init' ) ) {
		wp_cache_init();
	}

	try {
		wp();
		// template-loader.php declares no functions/constants (purely
		// procedural, ends in `include $template`), so a plain require is
		// safe on every request.
		require ABSPATH . WPINC . '/template-loader.php';
	} catch ( \Throwable $e ) {
		if ( ! headers_sent() ) {
			http_response_code( 500 );
		}
		error_log( '[devwp-worker] ' . $e->getMessage() );
	}
};

// Workers recycle after this many requests unless the environment overrides
// MAX_REQUESTS (FrankenPHP exposes environment variables through $_SERVER).
$max_requests = (int) ( $_SERVER['MAX_REQUESTS'] ?? {{MAX_REQUESTS}} );
for ( $i = 0; $i < $max_requests; $i++ ) {
	$keep_running = frankenphp_handle_request( $handler );

	// Call the garbage collector between requests so it does not trigger in
	// the middle of a page generation.
	gc_collect_cycles();

	// Recycle early when approaching the memory limit.
	$limit = (string) ini_get( 'memory_limit' );
	if ( preg_match( '/^(\d+)([KMG]?)$/i', $limit, $m ) === 1 ) {
		$bytes = (int) $m[1] * match ( strtoupper( $m[2] ) ) {
			'K' => 1024,
			'M' => 1024 ** 2,
			'G' => 1024 ** 3,
			default => 1,
		};
		if ( $bytes > 0 && memory_get_usage() > 0.8 * $bytes ) {
			break;
		}
	}

	if ( ! $keep_running ) {
		break;
	}
}
